import torch


def run(input, other):
    return torch.fmax(input, other)


def gen_inputs(ctx, device):
    import torch

    shape = ctx["input__shape"]
    dtype = getattr(torch, ctx["input__dtype"])
    inp1 = torch.randn(shape, dtype=dtype, device=device)
    inp2 = torch.randn(shape, dtype=dtype, device=device)
    nan_mask1 = torch.rand(shape, device=device) < 0.2
    nan_mask2 = torch.rand(shape, device=device) < 0.2
    inp1[nan_mask1] = float("nan")
    inp2[nan_mask2] = float("nan")
    return {"input": inp1, "other": inp2}


def valid(ref_outputs, sol_outputs, inputs, ctx):
    import torch

    ref = ref_outputs[0].detach().to("cpu")
    sol = sol_outputs[0].detach().to("cpu")
    if ref.shape != sol.shape:
        return {"passed": False, "message": f"shape {sol.shape} vs {ref.shape}", "metrics": {}}
    both_nan = torch.isnan(ref) & torch.isnan(sol)
    eq = (ref == sol) | both_nan
    ok = eq.all().item()
    return {"passed": bool(ok), "message": "", "metrics": {}}
